#ifndef OPENTITAN_SW_DEVICE_TESTS_EG2_NIST_EG2_NIST_H_
#define OPENTITAN_SW_DEVICE_TESTS_EG2_NIST_EG2_NIST_H_

/**
 * @file
 * @brief The NIST CAVP chip tests' vector tables and runner (spec: NIST CAVP Test Suite).
 *
 * A test's table is generated by gen_nist_vectors.py from the CAVP files OpenTitan pins: a pool
 * per vector file of boundary vectors, which always run, and random vectors, of which the run
 * draws `random_vectors` with the software seed (kEg2Seed). Values are NIST byte strings in
 * `kEg2NistPool`, addressed by offset: the tables hold no pointers.
 *
 * The test supplies one function that runs a vector on its engine and checks the result with
 * `eg2_nist_expect`. With the test's `_INJECT_FAIL` define, the first vector's expected value is
 * corrupted: that run must fail (the check is live).
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

enum {
  kEg2NistFields = 9,
  // Field indices (gen_nist_vectors.py).
  kEg2NistKey = 0,
  kEg2NistIv = 1,
  kEg2NistIn = 2,
  kEg2NistOut = 3,
  kEg2NistAad = 4,
  kEg2NistTag = 5,
  kEg2NistMsg = 2,
  kEg2NistMd = 3,
  kEg2NistMac = 3,
  kEg2NistEnt = 0,
  kEg2NistPers = 1,
  kEg2NistEntReseed = 2,
  kEg2NistAddReseed = 3,
  kEg2NistAdd1 = 4,
  kEg2NistAdd2 = 5,
  kEg2NistEntPr1 = 6,
  kEg2NistEntPr2 = 7,
  kEg2NistReturned = 8,
  // Flags.
  kEg2NistBoundary = 1,
  kEg2NistDecrypt = 2,
  kEg2NistFail = 4,
  kEg2NistMonte = 8,
  kEg2NistShake = 16,
  kEg2NistPr = 32,
  kEg2NistReseed = 64,
  kEg2NistSign = 128,
  // ecdsa fields
  kEg2NistEcdsaE = 0,
  kEg2NistEcdsaR = 1,
  kEg2NistEcdsaS = 2,
  kEg2NistEcdsaQx = 3,
  kEg2NistEcdsaQy = 4,
  kEg2NistEcdsaD0 = 5,
  kEg2NistEcdsaD1 = 6,
  kEg2NistEcdsaK0 = 7,
  kEg2NistEcdsaK1 = 8,
  // ecdh fields
  kEg2NistEcdhQx = 0,
  kEg2NistEcdhQy = 1,
  kEg2NistEcdhD0 = 2,
  kEg2NistEcdhD1 = 3,
  kEg2NistEcdhZ = 4,
  // rsa fields
  kEg2NistRsaN = 0,
  kEg2NistRsaE = 1,
  kEg2NistRsaS = 2,
  kEg2NistRsaEm = 3,
  kEg2NistRsaD0 = 4,
  kEg2NistRsaD1 = 5,
};

typedef struct eg2_nist_vec {
  uint16_t file;   // index of its file (kEg2NistFileName)
  uint32_t count;  // COUNT, or Len for the hash files
  uint16_t flags;
  uint16_t param;  // kind specific: AES mode bit, digest bits, ReturnedBitsLen
  uint32_t off[kEg2NistFields];
  uint32_t len[kEg2NistFields];
} eg2_nist_vec_t;

// The generated table.
extern const char kEg2NistFileNames[];
extern const uint16_t kEg2NistFileName[];
extern const uint32_t kEg2NistNumFiles;
extern const eg2_nist_vec_t kEg2NistVecs[];
extern const uint32_t kEg2NistNumVecs;
extern const uint8_t kEg2NistPool[];
// The vectors of the algorithm's files this test does not run, one NUL-terminated line per file
// and reason ("SigVer.rsp: 975 vectors (curve without an OTBN program ...)").
extern const char kEg2NistNotRun[];
extern const uint32_t kEg2NistNotRunCount;

/** A field's bytes and length. */
static inline const uint8_t *eg2_nist_data(const eg2_nist_vec_t *v, int field) {
  return &kEg2NistPool[v->off[field]];
}
static inline uint32_t eg2_nist_len(const eg2_nist_vec_t *v, int field) { return v->len[field]; }

/**
 * Runs one vector on the engine and checks it; `corrupt` is passed on to `eg2_nist_expect`.
 * Returns kEg2NistPassed, kEg2NistFailed (after printing why) or kEg2NistSkipped (a knob left
 * the vector out, e.g. Monte Carlo vectors with `monte` 0; printed by `eg2_nist_skip`).
 */
typedef enum eg2_nist_result {
  kEg2NistFailed = 0,
  kEg2NistPassed = 1,
  kEg2NistSkipped = 2,
} eg2_nist_result_t;
typedef eg2_nist_result_t (*eg2_nist_run_fn_t)(const eg2_nist_vec_t *v, bool corrupt);

/** A vector a knob leaves out: counted per file and reported, never passed. */
eg2_nist_result_t eg2_nist_skip(const eg2_nist_vec_t *v, const char *why);

/** kEg2NistPassed if ok, else kEg2NistFailed. */
static inline eg2_nist_result_t eg2_nist_result(bool ok) {
  return ok ? kEg2NistPassed : kEg2NistFailed;
}

/**
 * Runs `boundary_draws` of the boundary vectors drawn with eg2_rand() (all of them when 0), then
 * `random_draws` of the others; prints a line per vector as it starts, one per file and a total.
 * Returns true if every vector passed.
 */
bool eg2_nist_run(const char *engine, eg2_nist_run_fn_t fn, uint32_t boundary_draws,
                  uint32_t random_draws, bool inject_fail);

/** True in a test built with -DEG2_NIST_INJECT_FAIL (the define reaches only the test's source). */
#ifdef EG2_NIST_INJECT_FAIL
#define EG2_NIST_INJECT true
#else
#define EG2_NIST_INJECT false
#endif

/**
 * Compares `got` with the vector's field `field` (the first `len` bytes of it); with `corrupt`,
 * the expected value's first bit is flipped first. Prints the vector and both values on a
 * mismatch.
 */
bool eg2_nist_expect(const eg2_nist_vec_t *v, int field, const uint8_t *got, uint32_t len,
                     bool corrupt);

/** Prints `what` for the vector (an engine error). Returns false. */
bool eg2_nist_error(const eg2_nist_vec_t *v, const char *what);

/** Word i of a NIST byte string of nbytes, least significant word first (CSRNG's order). */
uint32_t eg2_nist_word(const uint8_t *b, uint32_t nbytes, uint32_t i);

#endif  // OPENTITAN_SW_DEVICE_TESTS_EG2_NIST_EG2_NIST_H_
